// Render the deployed guide.md as the Guide tab. The markdown subset here is
// exactly what the guide uses — headings, bold, code, fenced blocks, tables,
// lists, rules, links — rendered by hand because pulling a CDN parser into an
// admin page is a bigger dependency than sixty lines of string handling.

const esc = (s) => String(s == null ? '' : s)
  .replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');

let raw = null;
try {
  const j = $('Fetch the guide').first().json;
  raw = typeof j === 'string' ? j : (j.data ?? j.body ?? null);
  if (raw && typeof raw !== 'string') raw = null;
} catch (e) { raw = null; }

const inline = (t) => esc(t)
  .replace(/`([^`]+)`/g, '<code>$1</code>')
  .replace(/\*\*([^*]+)\*\*/g, '<strong>$1</strong>')
  .replace(/\*([^*]+)\*/g, '<em>$1</em>')
  .replace(/\[([^\]]+)\]\(([^)\s]+)\)/g, '<a href="$2">$1</a>');

function render(md) {
  const out = [];
  const lines = md.split('\n');
  let i = 0, para = [], list = null;
  const flushPara = () => { if (para.length) { out.push('<p>'+inline(para.join(' '))+'</p>'); para = []; } };
  const flushList = () => { if (list) { out.push('<ul>'+list.map(x=>'<li>'+inline(x)+'</li>').join('')+'</ul>'); list = null; } };
  while (i < lines.length) {
    const l = lines[i];
    if (l.startsWith('```')) {
      flushPara(); flushList();
      const buf = []; i++;
      while (i < lines.length && !lines[i].startsWith('```')) buf.push(lines[i++]);
      out.push('<pre><code>'+esc(buf.join('\n'))+'</code></pre>'); i++; continue;
    }
    if (/^\|/.test(l)) {
      flushPara(); flushList();
      const rows = [];
      while (i < lines.length && /^\|/.test(lines[i])) rows.push(lines[i++]);
      const cells = (r) => r.replace(/^\||\|$/g,'').split('|').map(c=>c.trim());
      let html = '<table>';
      rows.forEach((r, ri) => {
        if (/^\|[\s\-|:]+\|$/.test(r)) return;           // separator row
        const tag = ri === 0 ? 'th' : 'td';
        html += '<tr>'+cells(r).map(c=>`<${tag}>`+inline(c)+`</${tag}>`).join('')+'</tr>';
      });
      out.push(html+'</table>'); continue;
    }
    const h = l.match(/^(#{1,3})\s+(.*)/);
    if (h) { flushPara(); flushList();
      out.push(`<h${h[1].length}>`+inline(h[2])+`</h${h[1].length}>`); i++; continue; }
    if (/^---+\s*$/.test(l)) { flushPara(); flushList(); out.push('<hr>'); i++; continue; }
    const li = l.match(/^[-*]\s+(.*)/);
    if (li) { flushPara(); (list = list || []).push(li[1]); i++; continue; }
    if (l.trim() === '') { flushPara(); flushList(); i++; continue; }
    para.push(l.trim()); i++;
  }
  flushPara(); flushList();
  return out.join('\n');
}

const body = raw
  ? render(raw)
  : `<h1>The guide is not where it should be</h1>
     <p>/guide.md did not answer. The guide deploys with the n8n playbook —
     run <code>deploy-n8n.yml</code> on the VPS, and if this persists check
     that <code>/opt/guide/guide.md</code> exists.</p>`;

const html = `<!doctype html><html lang="en"><head><meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<meta name="robots" content="noindex">
<link rel="preconnect" href="https://fonts.googleapis.com">
