  <a class="out" href="/oauth2/sign_out?rd=https%3A%2F%2Flogin.microsoftonline.com%2F0f8703ae-7d51-4894-b66e-75f73e64a903%2Foauth2%2Fv2.0%2Flogout%3Fpost_logout_redirect_uri%3Dhttps%253A%252F%252Fdashboard.itsurgery.me%252Fsigned-out">Sign out</a>
</header>
<main>${body}</main></body></html>`;

return [{ json: { html } }];
